/* 다크 테마 전환: 루트의 .dark 클래스 */
@custom-variant dark (&:is(.dark *));

/* 전시 페이지에서 hover/focus를 정적으로 보여주기 위한 강제 변형.
   .state-hover 안의 자손은 마우스가 없어도 hover 스타일을 받는다.
   PropertyBlock과 StatePage 외의 곳에서는 이 클래스를 쓰지 않는다. */
@custom-variant hover {
  &:hover { @media (hover: hover) { @slot } }
  .state-hover & { @slot }
}
@custom-variant focus-visible (&:focus-visible, .state-focus &);
/* File Upload의 드래그 오버 상태. 실제로는 파일을 끌고 영역 위에 왔을 때만
   data-dragging="true"가 붙는다 — .state-dragging 안의 자손은 끌지 않아도
   그 스타일을 강제로 받는다. */
@custom-variant dragging (&[data-dragging='true'], .state-dragging &);

:root {
  --radius: 0.5rem;

  --background: oklch(1 0 0);
  --foreground: oklch(0.145 0 0);
  --surface: oklch(1 0 0);
  --surface-raised: oklch(0.985 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.145 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.145 0 0);
  --primary: oklch(0.205 0 0);
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.97 0 0);
  --secondary-foreground: oklch(0.205 0 0);
  /*
   * --surface-raised(0.985)와 명도가 거의 같아(0.97) 대비 1.04:1 — 다크에서는
   * 아예 같은 값이 되는 문제의 라이트 쪽 절반이다(아래 .dark의 --muted 주석
   * 참고). --surface-raised는 카드·스테이지·표 머리 등 훨씬 넓게 쓰여 손대지
   * 않고, 채움 쪽인 --muted만 명도를 0.93으로 낮췄다 — 라이트에서 --card·
   * --surface·--background는 모두 1.0으로 같은 값이라 그 위에서는 1.23:1,
   * 이 넷 중 가장 타이트한 --surface-raised(0.985) 위에서는 1.17:1로
   * 갈라져 Skeleton·Progress 트랙이 카드를 포함한 어떤 표면 위에서도
   * 도형으로 읽힌다.
   */
  --muted: oklch(0.93 0 0);
  /*
   * --muted가 0.97→0.93으로 낮아지며(바로 위 주석) 예전 0.523(0.556에서 한 차례
   * 낮춘 값)으로는 새 --muted 위에서 4.5:1에 못 미쳤다(4.41:1). 명도만 0.5로
   * 다시 낮춰 새 --muted(0.93) 위에서 4.90:1, Alert·Toast의 bg-destructive/10
   * 탄 배경(가장 어두운 조합) 위에서는 4.82:1 — Avatar 대체 글자·Table 담당자
   * 칸·Anatomy 번호 배지가 전부 이 토큰 하나를 물려받는다. 채도·색상은 그대로
   * 두고 명도만 낮췄다 — 더 어둡게 하면 '덜 중요한 글자'라는 위계가 본문과
   * 구별되지 않는다.
   */
  --muted-foreground: oklch(0.5 0 0);
  --accent: oklch(0.97 0 0);
  --accent-foreground: oklch(0.205 0 0);
  --destructive: oklch(0.577 0.245 27.325);
  --destructive-foreground: oklch(0.985 0 0);
  --success: oklch(0.596 0.145 163.225);
  --success-foreground: oklch(0.985 0 0);
  --warning: oklch(0.769 0.188 70.08);
  --warning-foreground: oklch(0.145 0 0);
  --info: oklch(0.6 0.118 264.376);
  --info-foreground: oklch(0.985 0 0);
  --border: oklch(0.922 0 0);
  --input: oklch(0.922 0 0);
  --ring: oklch(0.708 0 0);

  /*
   * 옅게 탄 배경(예: bg-info/15) 위에 얹는 글자색이다. *-foreground는 이미
   * 불투명한 배경(예: bg-info)과 짝지어 확인됐지만, 배경을 15%만 탄 다음
   * 원래 색을 그대로 글자에 쓰면 라이트 테마에서 대비가 4.5:1을 넘지
   * 못한다 — 채도(C)·색상(H)은 그대로 두고 명도(L)만 낮춰 각 색이 자기
   * 몫의 옅은 배경 위에서 4.5:1을 넉넉히 넘도록 다시 잡았다. neutral은
   * 상태색이 아니라 무채색이지만 같은 칩 패턴(Badge)에 쓰인다. muted-foreground도
   * 이제 라이트에서 명도를 낮췄지만(위 주석 참고) 그 값은 Alert·Toast의
   * 더 어두운 탄 배경에 맞춘 것이라, Badge의 opaque --muted 배경 하나에만
   * 맞춘 이 토큰과는 목표 배경이 달라 계속 따로 둔다.
   */
  --neutral-on-tint: oklch(0.51 0 0);
  --info-on-tint: oklch(0.525 0.118 264.376);
  --success-on-tint: oklch(0.492 0.145 163.225);
  --warning-on-tint: oklch(0.542 0.188 70.08);
  --destructive-on-tint: oklch(0.496 0.245 27.325);

  /*
   * 문서 주석 전용. 제품 UI에는 쓰지 않는다 — 컴포넌트 색과 절대 겹치지 않아야 한다.
   * annotation-muted는 Anatomy의 좁은 화면 번호 배지(bg-annotation-muted
   * text-background)에서 흰 글자를 얹는 바탕으로도 쓰인다 — 원래 명도(0.7)로는
   * 2.77:1이라 라이트에서 명도를 낮췄다. 이 토큰은 그 배지 하나에만 쓰여 다른
   * 곳에 번지지 않는다.
   */
  --annotation: oklch(0.55 0.22 285);
  --annotation-muted: oklch(0.573 0.14 285);
}

.dark {
  --background: oklch(0.145 0 0);
  --foreground: oklch(0.985 0 0);
  --surface: oklch(0.205 0 0);
  --surface-raised: oklch(0.269 0 0);
  --card: oklch(0.205 0 0);
  --card-foreground: oklch(0.985 0 0);
  --popover: oklch(0.205 0 0);
  --popover-foreground: oklch(0.985 0 0);
  --primary: oklch(0.922 0 0);
  --primary-foreground: oklch(0.205 0 0);
  --secondary: oklch(0.269 0 0);
  --secondary-foreground: oklch(0.985 0 0);
  /*
   * --surface-raised와 완전히 같은 값(0.269)이었다 — Skeleton·Progress 트랙이
   * bg-surface-raised 스테이지 위에서 대비 1:1로 완전히 사라졌다. 처음엔
   * 0.21로만 낮췄는데, 그러면 --surface·--card(둘 다 0.205)와 거의 같은
   * 값(1.01:1)이 되어 결함이 다른 표면으로 옮겨갈 뿐이었다 — 기본 Card
   * 변형(outlined)이 bg-card를 쓰므로 실제 카드 위에서 그대로 재현됐다.
   * --muted는 --background(0.145)·--surface·--card(0.205)·--surface-raised
   * (0.269) 네 표면 모두와 갈라져야 해서 0.32로 다시 잡았다 — --background
   * 위 1.57:1, --surface·--card 위 1.42:1, 넷 중 가장 타이트한
   * --surface-raised 위 1.20:1. --muted-foreground(0.708)는 이 --muted
   * 위에서도 4.89:1이라 함께 옮기지 않았다.
   */
  --muted: oklch(0.32 0 0);
  --muted-foreground: oklch(0.708 0 0);
  --accent: oklch(0.269 0 0);
  --accent-foreground: oklch(0.985 0 0);
  --destructive: oklch(0.704 0.191 22.216);
  --destructive-foreground: oklch(0.985 0 0);
  --success: oklch(0.696 0.17 162.48);
  --success-foreground: oklch(0.145 0 0);
  --warning: oklch(0.828 0.189 84.429);
  --warning-foreground: oklch(0.145 0 0);
  --info: oklch(0.707 0.165 254.624);
  --info-foreground: oklch(0.145 0 0);
  --border: oklch(1 0 0 / 12%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.556 0 0);

  /* 다크에서는 원래 색을 옅은 배경 위에 그대로 써도 이미 4.5:1을 넘는다 — 따로 낮추지 않는다 */
  --neutral-on-tint: var(--muted-foreground);
  --info-on-tint: var(--info);
  --success-on-tint: var(--success);
  --warning-on-tint: var(--warning);
  --destructive-on-tint: var(--destructive);

  --annotation: oklch(0.75 0.16 285);
  --annotation-muted: oklch(0.62 0.12 285);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-surface: var(--surface);
  --color-surface-raised: var(--surface-raised);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-info: var(--info);
  --color-info-foreground: var(--info-foreground);
  --color-neutral-on-tint: var(--neutral-on-tint);
  --color-info-on-tint: var(--info-on-tint);
  --color-success-on-tint: var(--success-on-tint);
  --color-warning-on-tint: var(--warning-on-tint);
  --color-destructive-on-tint: var(--destructive-on-tint);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-annotation: var(--annotation);
  --color-annotation-muted: var(--annotation-muted);

  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);

  /* 어드민 정보 밀도 축. 테이블 행과 컨트롤 높이를 한 곳에서 통제한다. */
  --spacing-control-sm: 2rem;
  --spacing-control: 2.25rem;
  --spacing-control-lg: 2.5rem;
  --spacing-row: 3rem;
  --spacing-row-compact: 2.5rem;

  --shadow-card: 0 1px 2px 0 oklch(0 0 0 / 0.04);
  --shadow-popover: 0 8px 24px -6px oklch(0 0 0 / 0.12);

  /*
   * 열두 단계(text-11~text-48) 전부의 크기와 줄 간격을 Tailwind 기본값 대신 새로
   * 정의한다. 이름도 픽셀 값으로 바꿔 text-lg·text-xl 같은 T셔츠 이름은 이제 없다.
   * 기본값 비율(1.33·1.43·1.5 안팎)로는 한 줄이 길어지면 글자벽으로 읽힌다 —
   * 한글은 음절이 네모 덩어리라 같은 비율에서도 라틴 문자보다 빽빽해 보인다.
   * 값은 전부 4의 배수인 정수 픽셀로 잡았다. Spacing 문서가 정한 간격 규칙이
   * 4px 배수(4·8·12·16·24·32·40·48·64)라서, 줄 상자 높이도 같은 눈금에 놓여야
   * 컨트롤 높이와 어긋나지 않는다.
   *
   * text-11(11px, 옛 이름 text-2xs)은 자격 조건 셋을 모두 만족할 때만 쓴다 —
   * ① 그 글자가 유일한 정보원이 아니다(옆의 아이콘·색·더 큰 글자가 같은 뜻을
   * 이미 전달해, 이 글자가 안 읽혀도 과업을 끝낼 수 있다). ② 한두 글자
   * 수준으로 극히 짧다. ③ 담는 그릇의 크기가 이 시스템의 다른 규칙(아이콘
   * 지름, 그리드 칸 폭 등)에 못 박혀 있다 — "좁아 보여서"는 조건이 아니다.
   *
   * 값은 남겨 두지만 지금 이 셋을 다 통과하는 자리는 코드베이스 어디에도
   * 없다. Badge·메뉴 그룹 라벨·요일 머리가 전에는 이 값을 썼지만 셋 다
   * ③이 거짓이었다(text-12로 올려도 안 깨졌다) — 그래서 실제로 쓰는 최소
   * 크기는 text-12부터다. 자세한 사정은 TypographyPage의 Scale을 본다.
   */
  --text-11: 0.6875rem;
  --text-11--line-height: 1rem;

  --text-12: 0.75rem;
  --text-12--line-height: 1.25rem;

  --text-14: 0.875rem;
  --text-14--line-height: 1.5rem;

  --text-16: 1rem;
  --text-16--line-height: 1.75rem;

  --text-18: 1.125rem;
  --text-18--line-height: 1.75rem;

  --text-20: 1.25rem;
  --text-20--line-height: 1.75rem;

  --text-22: 1.375rem;
  --text-22--line-height: 2rem;

  --text-24: 1.5rem;
  --text-24--line-height: 2rem;

  --text-28: 1.75rem;
  --text-28--line-height: 2.5rem;

  --text-32: 2rem;
  --text-32--line-height: 2.75rem;

  --text-40: 2.5rem;
  --text-40--line-height: 3.25rem;

  --text-48: 3rem;
  --text-48--line-height: 4rem;

  /* Pretendard를 앞에 두고 시스템 폰트를 폴백으로 남긴다.
     CDN이 막히거나 폰트가 아직 오지 않아도 한글이 깨지지 않게 한다. */
  --font-sans:
    'Pretendard Variable', Pretendard, -apple-system, BlinkMacSystemFont, system-ui, Roboto,
    'Helvetica Neue', 'Segoe UI', 'Apple SD Gothic Neo', 'Noto Sans KR', 'Malgun Gothic',
    sans-serif;

  /* z-index 레이어. 값이 컴포넌트마다 흩어지지 않게 한 곳에 모은다.
     Tailwind v4는 --z-index-* 네임스페이스를 z-* 유틸리티로 노출한다. */
  --z-index-sticky: 10;
  --z-index-drawer: 20;
  --z-index-overlay: 30;
  --z-index-popover: 40;
  --z-index-toast: 50;

  /* Progress의 indeterminate 상태. 값을 모를 때 좁힌 Indicator(w-1/3)가
     track을 가로질러 오간다. tailwindcss/theme.css의 --animate-spin과
     같은 자리에 같은 방식(--animate-* 토큰 + 중첩 @keyframes)으로 둔다. */
  --animate-progress-indeterminate: progress-indeterminate 1.4s ease-in-out infinite;

  @keyframes progress-indeterminate {
    from {
      transform: translateX(-100%);
    }
    to {
      transform: translateX(400%);
    }
  }
}

/*
 * 모바일(md 미만, 768px)에서는 text-11·text-12를 강제로 text-14 크기로
 * 올린다. --text-12 같은 변수를 media query 안에서 다시 정의하는 식으로는
 * 안 된다 — Tailwind가 .text-12 유틸리티를 구울 때 font-size에
 * var(--text-12)가 아니라 0.75rem 같은 값을 직접 박아 넣는다(실측
 * 확인: getComputedStyle이 아니라 실제 생성된 CSSRule.cssText로 봤다).
 * 그래서 변수만 바꿔서는 이미 구워진 유틸리티에 아무 영향이 없고,
 * .text-11·.text-12 셀렉터 자체를 다시 겨눠야 한다.
 *
 * @layer 밖에 둔다 — Tailwind가 만든 유틸리티는 전부 @layer utilities
 * 안에 있고, CSS Cascade Layers 규칙상 계층 밖의 스타일은 명시도나
 * 소스 순서와 무관하게 계층 안의 스타일을 항상 이긴다. 그래서 이 블록을
 * 파일 어디에 둬도(굳이 뒤에 두지 않아도) 이긴다 — 여기 둔 것은 오직
 * text-11·text-12 값 옆이라 읽기 쉬워서다.
 *
 * text-14(0.875rem)로 올린다 — 이 시스템에 이미 있는 단계를 그대로
 * 쓴 것이지 새 크기를 만든 게 아니다. text-11·12를 쓰던 자리(Badge·
 * 표 머리·캡션 등)가 모바일에서는 전부 이 값으로 커진다.
 */
@media (max-width: 767px) {
  .text-11,
  .text-12 {
    font-size: var(--text-14);
    line-height: var(--text-14--line-height);
  }
}

@layer base {
  * {
    border-color: var(--color-border);
  }

  /*
   * 셸은 h-dvh로 화면 높이에 고정되고 스크롤은 main 혼자 맡는다.
   * 그런데 앵커로 이동해 제목을 화면에 넣을 때 브라우저가 main뿐 아니라
   * 문서(html)까지 함께 굴려, GNB가 위로 밀려 나간 채 돌아오지 않는다.
   * 문서 레벨은 애초에 스크롤할 여지가 없어야 하므로 여기서 막는다.
   */
  html,
  body {
    overflow: hidden;
  }

  body {
    background-color: var(--color-background);
    color: var(--color-foreground);
    -webkit-font-smoothing: antialiased;
    margin: 0;
    /* font-sans 유틸리티를 쓰지 않은 곳까지 같은 스택으로 덮는다 */
    font-family: var(--font-sans);
    /* 한글은 음절 단위로 줄바꿈한다. 어절 단위로 묶으면 좁은 화면에서 한 줄이 크게 빈다 */
    word-break: normal;
    overflow-wrap: break-word;
  }
}

/*
 * 스크롤 막대만 감춘다. 스크롤 자체는 막지 않는다.
 * 두 줄이 필요하다 — 앞은 Firefox, 뒤는 WebKit이다.
 */
@utility scrollbar-none {
  scrollbar-width: none;
  &::-webkit-scrollbar {
    display: none;
  }
}
